import csv
import io

def summarize_expenses(csv_text):
    """Total the amount column per category.

    Returns {category: total} with each total rounded to 2 decimals.
    Category keys are lowercase with surrounding whitespace stripped.
    Amounts may be quoted and may use $ and thousands separators.
    An amount wrapped in parentheses is negative, accounting style.
    Rows with a missing or empty amount are skipped, as are blank lines.
    """
    totals = {}
    f = io.StringIO(csv_text.strip())
    reader = csv.DictReader(f)
    for row in reader:
        cat_raw = row.get('category')
        amt_raw = row.get('amount')
        if cat_raw is None or amt_raw is None or amt_raw.strip() == "":
            continue

        cat = cat_raw.strip().lower()

        # Parse amount
        s = amt_raw.strip()
        if not s:
            continue

        is_negative = False
        if s.startswith('(') and s.endswith(')'):
            is_negative = True
            s = s[1:-1]

        s = s.replace('$', '').replace(',', '')
        try:
            val = float(s)
            if is_negative:
                val = -val
            totals[cat] = totals.get(cat, 0) + val
        except ValueError:
            continue

    return {k: round(v, 2) for k, v in totals.items()}
